From 6587dcd231eeb2fdf33ab2cb868d315d6404fac1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:39:30 +0100
Subject: [PATCH] applets/notifications: Keep popups on screen next to a short
 panel

Popups near the widget were placed in an area cut down to the panel, so
a popup wider than a short right-aligned panel went past the screen
edge. Keep aligning popups to the panel, but clamp them to the screen.

BUG: 473027
---
 applets/notifications/global/Globals.qml | 38 ++++++++++++++++--------
 1 file changed, 25 insertions(+), 13 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..182563b24f 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -124,6 +124,7 @@ QtObject {
         }
     }

+    // The area popups have to stay in
     readonly property rect screenRect: {
         if (!plasmoid) {
             return Qt.rect(0, 0, -1, -1);
@@ -134,13 +135,16 @@ QtObject {
             return Qt.rect(0, 0, -1, -1);
         }
         // NOTE this is our "plasmoid" property from above, don't port this to Plasmoid attached property!
-        let rect = Qt.rect(containment.screenGeometry.x + containment.availableScreenRect.x,
-                           containment.screenGeometry.y + containment.availableScreenRect.y,
-                           containment.availableScreenRect.width,
-                           containment.availableScreenRect.height);
+        return Qt.rect(containment.screenGeometry.x + containment.availableScreenRect.x,
+                       containment.screenGeometry.y + containment.availableScreenRect.y,
+                       containment.availableScreenRect.width,
+                       containment.availableScreenRect.height);
+    }

-        // When no explicit screen corner is configured,
-        // restrict notification popup position by horizontal panel width
+    // The area popups are aligned to horizontally: when no explicit screen corner is configured,
+    // the part of the screen covered by the horizontal panel holding the widget
+    readonly property rect alignmentRect: {
+        let rect = screenRect;
         if (visualParent && notificationSettings.popupPosition === NotificationManager.Settings.CloseToWidget
             && plasmoid.formFactor === PlasmaCore.Types.Horizontal) {
             const visualParentWindow = visualParent.Window.window;
@@ -150,10 +154,10 @@ QtObject {
                 rect = Qt.rect(left, rect.y, right - left, rect.height);
             }
         }
-
         return rect;
     }
     onScreenRectChanged: repositionTimer.start()
+    onAlignmentRectChanged: repositionTimer.start()

     readonly property Item visualParent: {
         if (!plasmoidItem) {
@@ -380,13 +384,21 @@ QtObject {
             const leftMostX = screenRect.x + popupEdgeDistance;
             const rightMostX = screenRect.x + screenRect.width - popupEdgeDistance - popup.width;

-            // If available screen rect is narrower than the popup, center it in the available rect
-            if (screenRect.width < popup.width || effectivePopupLocation & Qt.AlignHCenter) {
+            // If the screen is narrower than the popup, center it on the screen
+            if (rightMostX < leftMostX) {
                 popup.x = screenRect.x + (screenRect.width - popup.width) / 2
-            } else if (effectivePopupLocation & Qt.AlignLeft) {
-                popup.x = leftMostX;
-            } else if (effectivePopupLocation & Qt.AlignRight) {
-                popup.x = rightMostX;
+            } else {
+                // If the alignment rect is narrower than the popup, center it on the alignment rect
+                let x;
+                if (alignmentRect.width < popup.width || effectivePopupLocation & Qt.AlignHCenter) {
+                    x = alignmentRect.x + (alignmentRect.width - popup.width) / 2;
+                } else if (effectivePopupLocation & Qt.AlignLeft) {
+                    x = alignmentRect.x + popupEdgeDistance;
+                } else {
+                    x = alignmentRect.x + alignmentRect.width - popupEdgeDistance - popup.width;
+                }
+                // but never past the screen edges
+                popup.x = Math.max(leftMostX, Math.min(x, rightMostX));
             }

             if (effectivePopupLocation & Qt.AlignTop) {
